window.__posterData({"id": "elias-nordenberg", "name": "Elias Nordenberg", "folder": "raveposter - AI_Elias_Nordenberg_DIK_HT26", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "const CANVAS_WIDTH = 600;\nconst CANVAS_HEIGHT = 800;\nconst BALL_SIZE = 30;\nconst BALL_COUNT = 20;\nconst BACKGROUND_IMAGE = 'rave_background (1).jpg';\nconst COLORS = ['#ffff', '#7BF004', '#FC05B8', '#FFFF0F', '#FA6B05', '#0FB7FF'];\n\nconst SQUISH_AMOUNT = 0.4;  // how much a drop flattens on impact\nconst SQUISH_DECAY = 0.88;  // how fast it wobbles back to round (closer to 1 = slower)\n\nconst RIPPLE_SPEED = 7;        // how fast the ring expands (pixels per frame)\nconst RIPPLE_MAX_RADIUS = 500; // ring disappears after this size\nconst RIPPLE_PUSH = 6;         // shove strength on a drop right at the click\nconst MAX_SPEED = 16;          // cap so repeated clicks can't make drops run away\n\nlet balls = [];\nlet ripples = [];\nlet img;\nlet colorIndex = 0;\n\nasync function setup() {\n  createCanvas(CANVAS_WIDTH, CANVAS_HEIGHT);\n  fill(COLORS[colorIndex]);\n\n  img = await loadImage(BACKGROUND_IMAGE);\n\n  // Random start position and speed for each ball\n  for (let i = 0; i < BALL_COUNT; i++) {\n    balls.push({\n      x: random(width - BALL_SIZE),\n      y: random(height - BALL_SIZE),\n      speedX: random(5, 10),\n      speedY: random(5, 10),\n      squish: 0,      // current flattening (0 = perfectly round)\n      squishAngle: 0, // direction of the last impact\n    });\n  }\n}\n\nfunction draw() {\n  background(0, 100, 250, 24);\n  image(img, 0, 0, width, height);\n\n  drawLabels();\n\n  for (const ball of balls) {\n    moveBall(ball);\n    bounceOffWalls(ball);\n  }\n\n  resolveCollisions();\n  updateRipples();\n  drawRipples();\n\n  strokeWeight(2);\n  for (const ball of balls) {\n    drawDrop(ball);\n  }\n}\n\nfunction drawLabels() {\n  textAlign(CENTER, CENTER);\n  textSize(100);\n  text('Sodertorn', 300, 150);\n  text('Rave', 300, 250);\n\n  textSize(40);\n  stroke(0);\n  strokeWeight(4);\n  text('Elias Nordenberg', 440, 775);\n}\n\nfunction moveBall(ball) {\n  ball.x += ball.speedX;\n  ball.y += ball.speedY;\n}\n\nfunction bounceOffWalls(ball) {\n  const maxX = width - BALL_SIZE;\n  const maxY = height - BALL_SIZE;\n\n  if (ball.x <= 0) {\n    ball.x = 1;\n    ball.speedX *= -1;\n  } else if (ball.x >= maxX) {\n    ball.x = maxX + 1;\n    ball.speedX *= -1;\n  }\n\n  if (ball.y <= 0) {\n    ball.y = 1;\n    ball.speedY *= -1;\n  } else if (ball.y >= maxY) {\n    ball.y = maxY + 1;\n    ball.speedY *= -1;\n  }\n}\n\n// Each pair is checked once. Drops push apart gently along the line between\n// their centers and exchange momentum along that line, like colliding water drops.\nfunction resolveCollisions() {\n  for (let i = 0; i < balls.length; i++) {\n    for (let j = i + 1; j < balls.length; j++) {\n      const a = balls[i];\n      const b = balls[j];\n\n      const dx = b.x - a.x;\n      const dy = b.y - a.y;\n      const distance = Math.hypot(dx, dy);\n      if (distance >= BALL_SIZE || distance === 0) continue;\n\n      // Collision direction (unit vector from a to b)\n      const nx = dx / distance;\n      const ny = dy / distance;\n\n      // Push both drops apart equally so they no longer overlap\n      const push = (BALL_SIZE - distance) / 2;\n      a.x -= nx * push;\n      a.y -= ny * push;\n      b.x += nx * push;\n      b.y += ny * push;\n\n      // Only exchange momentum if the drops are moving toward each other\n      const approach = (a.speedX - b.speedX) * nx + (a.speedY - b.speedY) * ny;\n      if (approach > 0) {\n        a.speedX -= approach * nx;\n        a.speedY -= approach * ny;\n        b.speedX += approach * nx;\n        b.speedY += approach * ny;\n      }\n\n      // Both drops flatten against each other\n      const angle = atan2(ny, nx);\n      a.squish = b.squish = SQUISH_AMOUNT;\n      a.squishAngle = b.squishAngle = angle;\n    }\n  }\n}\n\n// Draws the drop squashed along its impact direction, then wobbling back to round\nfunction drawDrop(ball) {\n  push();\n  translate(ball.x + BALL_SIZE / 2, ball.y + BALL_SIZE / 2);\n  rotate(ball.squishAngle);\n  ellipse(0, 0, BALL_SIZE * (1 - ball.squish), BALL_SIZE * (1 + ball.squish));\n  pop();\n\n  ball.squish *= SQUISH_DECAY;\n}\n\n// Expands each ripple and shoves every drop once, when the ring first reaches it\nfunction updateRipples() {\n  for (const ripple of ripples) {\n    ripple.radius += RIPPLE_SPEED;\n\n    for (const ball of balls) {\n      if (ripple.hit.has(ball)) continue;\n\n      const dx = ball.x + BALL_SIZE / 2 - ripple.x;\n      const dy = ball.y + BALL_SIZE / 2 - ripple.y;\n      const distance = Math.hypot(dx, dy);\n      if (distance > ripple.radius || distance === 0) continue;\n\n      ripple.hit.add(ball);\n\n      // The shove weakens as the ripple spreads out\n      const strength = RIPPLE_PUSH * (1 - ripple.radius / RIPPLE_MAX_RADIUS);\n      ball.speedX += (dx / distance) * strength;\n      ball.speedY += (dy / distance) * strength;\n\n      const speed = Math.hypot(ball.speedX, ball.speedY);\n      if (speed > MAX_SPEED) {\n        ball.speedX *= MAX_SPEED / speed;\n        ball.speedY *= MAX_SPEED / speed;\n      }\n\n      // The wave flattens the drop as it passes\n      ball.squish = SQUISH_AMOUNT;\n      ball.squishAngle = atan2(dy, dx);\n    }\n  }\n\n  ripples = ripples.filter((ripple) => ripple.radius < RIPPLE_MAX_RADIUS);\n}\n\n// Neon rings that fade out as they grow\nfunction drawRipples() {\n  push();\n  noFill();\n  for (const ripple of ripples) {\n    const fade = 1 - ripple.radius / RIPPLE_MAX_RADIUS;\n    const ringColor = color(ripple.color);\n    ringColor.setAlpha(255 * fade);\n    stroke(ringColor);\n    strokeWeight(2 + 4 * fade);\n    circle(ripple.x, ripple.y, ripple.radius * 2);\n  }\n  pop();\n}\n\n// Cycle the fill color on click and send out a ripple in that color\nfunction mousePressed() {\n  colorIndex++;\n  fill(COLORS[colorIndex]);\n\n  ripples.push({\n    x: mouseX,\n    y: mouseY,\n    radius: 0,\n    color: COLORS[colorIndex],\n    hit: new Set(), // drops this ripple has already pushed\n  });\n\n  if (colorIndex > 4) {\n    colorIndex = 0;\n  }\n}\n\n// My prompts:\n\n// Prompt 1\n// Refactor the code without changing functionality.\n\n// Prompts 2\n// The element in the code that makes the circles bounce of each other. Change that into a more waterdrop feel. Adjust the size to the circles so that they are 30 instead of 15. And instead of 150 circles, have 20.\n\n// Prompt 3\n// Suggest and implement 1 additional feature to this poster, something that YOU think is fun, such as an animation loop, interactive component, or something else. Use your best judgment given the current style and aesthetic.\n\n\n\n", "assets": {"rave_background (1).jpg": {"mime": "image/webp", "b64": ""}}});
